      "noticeText": "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2025.12.12 오후 4:01)\n----------------------------------------\n[2025-2학기 기말고사 간식행사 만족도 조사]\n\n안녕하세요, Duet 홍보국입니다.\n\n12월 11일 진행된 기말고사 간식행사의 전반적인 만족도를 조사하고 피드백을 받고자 합니다. 이후 간식행사의 발전을 위해 소중한 의견 남겨주시면 감사하겠습니다.\n\n18대 학생회 Duet의 임기 첫 사업인 간식행사에 참여해주신 모든 학우분들께 감사하다는 말씀 드립니다. 아쉽게 참여하지 못하신 학우분들께도 감사하다는 말씀 드리며, 모두 기말고사에서 좋은 결과 받으시길 응원합니다.\n\n설문 링크: https://forms.gle/fiLhVxMHtxCvbUFu6\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 & 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 간식행사 피드백 공지\n• 일시: 2025.12.12\n• 담당 국서: 홍보국\n• 진행 상태: 완료",
