      "noticeText": "[25~26학번 D반 뻔선뻔후 매칭 및 친해져도 Dㅐ? 안내]\n• 뻔라인 매칭 원칙:\n  1. 25학번 대상 사전 설문조사 실시 (뻔후 희망 여부, 외국인 배정 선호도, 2명 이상 추가 입양 가능 여부 조사)\n  2. 학번 끝 3자리가 같은 25·26학번을 '친뻔'으로 우선 매칭\n  3. 친뻔선이 없거나(200번대 학번 등) 미응답인 경우, 다수 배정을 자원한 25학번 선배('입양명단')에게 '입양' 매칭 및 새터 참여 여부(O/X) 표기 배포\n• 2026 친해져도 Dㅐ?: 2/23(월) 공지 업로드, 25학번 2명 + 26학번 2명(4인 1조) 매칭 신청 개시",
