      "title": "D반 반실 한 눈에 알아보기 공지",
      "summary": "개강 첫 주 반실 비품·대여사업(우산/보조배터리)·추억공간·홍보게시판·냉장고 4주 폐기 수칙 카드뉴스 11장 배포",
