      "noticeText": "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.03.17 오후 5:51)\n----------------------------------------\nD반 응원OT 개인 입장 인원 지금부터 입장 가능하나 대표자 인솔 필요하다고 합니다! 혹시 늦참하시는 분들 중 지금 입장원하시는 분 있으면 저에게 개별적으로 연락부탁드립니다.\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 & 회의 메모]\n[2026학년도 1학기 합동응원전 인원 배정 및 추첨 결과 안내]\n• 본행사(총 39명 확정): 사전 가수요 조사 참여자 25명 전원 우선 확정 + 추가 신청자 20명 중 엑셀 난수(=RAND()) 상위 14명 선발\n• 뒤풀이 1차(총 38명 확정): 신청자 43명 중 난수 상위 38명 선발 (하위 5명 예비)\n• 뒤풀이 2차(총 23명 확정): 신청자 33명 중 난수 상위 23명 선발 (하위 10명 예비)\n* 공정성과 투명성을 위해 추첨 엑셀 시트의 [이름 마스킹 + 학번 뒤 3자리 + 난수값(소수점 6~9자리)] 캡처본을 함께 공지합니다.",
      "thought": "• 합동응원전은 티켓 수량과 뒤풀이 식당 수용 인원이 제한되어 있어 선착순으로만 자르면 불만이 생기기 쉽습니다.\n• 그래서 '사전 가수요 조사에 성실히 응답한 학우(25명)는 100% 우선 보장'하되, 추가 신청자들에 대해서는 엑셀 RAND() 함수로 난수를 부여해 내림차순 정렬한 시트 전체(이름 가운데 마스킹 + 난수값)를 투명하게 공개했습니다. 한 건의 이의 제기도 없이 깔끔하게 진행되었습니다!"
