      "summary": "",
      "images": [],
      "noticeText": "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.04.28 오후 1:29)\n----------------------------------------\n🐯자유전공학부 막강 D반 총MT 실수요조사🐯\n\n안녕하세요, D반 제18대 학생회 Duet입니다. 새로운 학기의 중간고사가 끝남과 동시에 Duet의 기획국에서 D반 내의 끈끈한 친목 도모를 위한 MT를 준비했습니다! 시험기간의 스트레스를 풀고, 동기, 선후배들과 더더욱 친해질 기회이니 많은 관심 부탁드립니다. 참여를 희망하시는 분께서는 아래의 구글폼을 작성하시고 참가비를 송금해주시길 바랍니다.\n\n📎 신청 구글폼 링크: https://forms.gle/Ls9MqFMdBrJ3VPy27\n📎 신청기한:~5/1(금) 23:59시까지!\n\n📍 날짜: 5/8(금)-5/9(토)\n\n📍 장소: 대성리 뜨락 펜션 (경기도 남양주시 화도읍 모꼬지로17번길 37-34)\n\n📍참여금: 4만원 (입금자명: 학번 + 이름 / 예: 25 원준혁)\n\n📍입금계좌: 토스뱅크 [계좌번호 마스킹] 우상준\n\n📍본 실수요조사에 참여하신 분들에 한해 MT 참여자 톡방에 초대하여 필요한 내용을 공지할 예정입니다.\n\n| 문의: D반 학생회장 원준혁\n| 제작: 홍보국원 박준원\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 & 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: D반 총MT 실수요조사\n• 일시: 2026.04.28 ~ 05.01\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
