      "noticeText": "[26-1 스터디윗D 경품 추첨 일정 변경]\n안녕하세요, Duet입니다. \n\n작일 19시 반실에서 26-1학기 중간고사 스터디윗D 추첨을 진행하기 직전, 기존 명단과 실제 미션 달성 현황이 일치하지 않는 부분이 확인되었습니다.\n\n이에 따라 공정성을 기하기 위해 명단을 전수 재검토하기로 결정하였으며, 금일 18시에 추첨을 다시 진행할 예정입니다. 사전에 명단을 꼼꼼히 검토하지 못해 학우 여러분께 혼선과 불편을 드린 점 진심으로 사과드립니다.\n\n오래 기다려 주신 만큼 더욱 투명하고 정확하게 추첨을 진행하겠습니다.\n감사합니다.",
