      "title": "입실렌티 뒤풀이 실수요조사",
      "summary": "",
      "images": [],
      "noticeText": "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.05.11 오후 7:08)\n----------------------------------------\n[🐯 2026 입실렌티 뒤풀이 실수요조사🐯]\n\n안녕하세요! D반 제18대 학생회 Duet입니다. 다가오는 5월 22일 금요일, 입실렌티 이후 진행할 뒤풀이 참가 여부를 조사하고자 합니다. 이번 입실렌티 뒤풀이는 자유전공학부 A반과 함께 진행됩니다! 뒤풀이 참여를 희망하시는 분들은 신청 기간 내에 아래 설문에 참여해주시고 예약금을 꼭 입금해주시길 바랍니다. 많은 관심 부탁드립니다! \n\n📌 설문 링크: https://forms.gle/qkHJ2XGv8tazVden8\n📍 신청 기한: ~5/15(금) 23:59\n📍 장소: 심야식당 호랑이\n📍 일시: 5/22(금) 22:00~01:00\n\n✅ 예약금: 10,000원\n✅ 입금계좌: 토스뱅크 [계좌번호 마스킹] 우상준 \n✅ 입금명: 학번+성명 (ex. 25우상준) \n\n❗️D반에 배정된 입실렌티 뒤풀이 좌석은 33석입니다. 참여를 희망하는 인원수가 많을 경우 부득이하게 난수 추첨 배정이 이루어질 수 있다는 점 알려드립니다. 이 점 참고 부탁드립니다. 감사합니다! \n❗️ 5/15(금) 이후 예약금 환불은 불가합니다. 또한, 타행입출금으로 인한 수수료로 인하여 입금금액과 환불금액이 다를 수 있으니 신중히 신청 부탁드립니다.\n❗️ 구글폼 작성과 더불어 예약금 입금이 완료되어야 참석으로 간주되오니 잊지 말고 입금해주시길 부탁드립니다! \n\n* A반에 배당된 자리가 남는 경우 및 공석이 생기는 경우,  다음 순위 추첨자분께 배정될 예정입니다.\n* 구체적인 집결 시간, 장소 등의 입실렌티 관련 세부 사항들은 추후 상세히 공지가 될 예정입니다.\n\n문의: D반 학생회장 원준혁 010-3516-3561\nD반 부학생회장 우상준 010-5859-2581\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 & 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 입실렌티 뒤풀이 실수요조사\n• 일시: 2026.05.11 ~ 05.15\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
