      "noticeText": "[26-1 기말고사 스터디윗D 경품 추첨 안내]\n안녕하세요, Duet입니다. 금일 21시 15분 인스타 라이브 방송을 통해 26-1학기 기말고사 스터디윗D 추첨을 진행할 예정입니다. 미션 달성 인원 중 학생회비 납부자를 대상으로 진행됩니다. 추첨 진행 후 당첨자 목록을 공지할 예정이니 참고 부탁드립니다. 감사합니다.",
