      "title": "8월 국장단 회의",
      "summary": "7~8월 통합 월간보고 발행 결정, 행정실 지원 반실 소파 구매 협의 및 고장 의자 불용 신고(9/1), 8/26 반실 대청소, 8/30 고양전 참여",
      "images": [],
      "noticeText": "",
      "thought": "• 방학 중인 7월에는 기말 스터디윗D 추첨 발표 외에 대면 행사가 없는데 억지로 7월 월간보고를 따로 내기보다, 8월 말 대청소·고양전·가구 교체 준비까지 묶어 '7~8월 통합 월간보고'로 내는 것이 홍보국 피로도도 줄이고 콘텐츠 밀도도 높이는 합리적인 선택이었습니다.\n• 반실 내 대형 가구나 의자가 고장 났을 때 임의로 버리면 안 되고, 학부 행정팀(담당 직원분)에 문의해 '미등록 불용품 신고서(가로×세로×높이 규격 및 사진 첨부)' 결재를 받은 뒤 지정 위치(법학관 구관 1층 반실 앞/계단 좌측)에 배출해야 합니다."
