      "noticeText": "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.08.28 오후 6:19)\n----------------------------------------\n[🎉2026-2학기 D반 개강파티 실수요조사🎉]\n\n안녕하세요, D반 학생회장입니다. 2학기를 맞이하여 친목을 다지기 위해 개강파티를 진행하고자 합니다. 아래 구글폼을 통해 신청 부탁드립니다! 2학기 첫 공식 행사인 만큼 많은 관심 부탁드립니다!\n\n📍 일시: 9/4 19:00\n📍 장소: 박군포차(서울특별시 성북구 고려대로26길 34 1층)\nhttps://maps.app.goo.gl/aAdbCUNqaqpg5WRB8\n📎 예약금: 10,000원\n📎 입금 계좌: [계좌번호 마스킹] 토스뱅크 우상준\n📎 입금명: 학번 + 성명 (예: 25원준혁)\n📎 구글폼: https://forms.gle/dUmj6bJty4dJyCpF7\n\n*폼 작성과 더불어 예약금 입금을 완료해주셔야 참석으로 간주되오니 잊지 말고 입금하시길 바랍니다. 행사 전날 및 당일 취소 시 예약금은 환불이 어려운 점 양해 부탁드립니다.\n\n문의: 학생회장 원준혁 010-3516-3561\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 & 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 개강파티 실수요조사\n• 일시: 2026.08.28 ~ 09.02\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
