      "status": "완료",
      "title": "제18-10차 D반 운영위원회 회의",
      "summary": "제18-10차 반운위(대학생RUN 제휴 거절), 제18-11차 새벽 긴급 반운위(릴스 고연전 및 타교생 회비 분리 원칙), 제9차 국장단회의, 제18-12차 반운위(학부 선관위 2인 파견)",
      "images": [],
      "noticeText": "",
      "thought": "• 연세대 교류반과 '릴스 고연전'을 기획할 때 초기 연세대 측 가안에는 '고대+연대 연합팀 촬영 시 조회수 10% 가산' 조항이 있었으나, 새벽 2시 긴급 반운위(18-11차)에서 부학생회장과 신입생 대표가 '연합팀이 일반 시상을 받으면 D반 학생회비가 연세대 학생 상품에 쓰이게 된다'는 점을 정확히 짚어주었습니다. 덕분에 교내팀(학생회비 시상)과 연합팀(회비 미투입 특별상)을 깔끔하게 분리할 수 있었습니다.\n• 마지막으로 10월 말에는 「자유전공학부 선거시행세칙」 제152조에 따라 후보 등록 마감일 10일 전까지 반 운영위원회 의결을 거쳐 학부 선거관리위원회 위원 2명을 파견해야 하니 차기 회장단도 10월 중순~말 일정을 꼭 챙기시길 바랍니다!"
