      "title": "응원 OT 전날 공지",
      "summary": "",
      "images": [],
      "noticeText": "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.09.08 오후 7:57)\n----------------------------------------\n[2학기 응원OT 안내 공지]\n\n안녕하세요. 학생회장입니다. \n익일 예정되어 있는 2학기 응원OT 관련 안내 공지 드립니다.\n\n🧷집결 시간: 9/9(수) 17:10까지 \n🧷집결 장소: 동원글로벌리더십홀 앞 공터 \n\n📌응원OT 및 뒤풀이 신청 인원이 D반 배정 좌석 수를 넘지 않아 실수요조사에 응답하신 “전원 참여 가능”합니다.\n📌자유전공학부 배정 좌석은 첨부해드린 사진의 “N구역”입니다. 단체입장 시 앞에서부터 “A, B, C, D반 순”으로 착석할 예정입니다. \n📌단위별 단체 입장 시간에 맞춰 이동하기에 시간 엄수 부탁드립니다. 단체 입장 시간을 놓쳤거나 불가한 경우, 화정체육관에서 “18:00부터 개인 입장”이 가능합니다. 이 경우 학생회장에게 개인 연락 부탁드립니다.\n📌추가로 실수요조사에 응답하지 않았으나 참여를 원하는 등의 특별한 경우에도 꼭 학생회장에게 “개인 연락” 부탁드립니다. \n\n| 문의: D반 학생회장 원준혁\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 & 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 응원 OT 전날 공지\n• 일시: 2026.09.08\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
