      "summary": "",
      "images": [],
      "noticeText": "[2026학년도 2학기 D반 중간고사 간식행사]\n\n안녕하세요, 제18대 D반 학생회 Duet 복지국입니다.\n\n학우 여러분의 2학기 중간고사 응원을 위해 [D반 중간고사 간식행사]를 진행합니다! 많은 참여 부탁드립니다.\n\n학우분들을 대상으로 한 간식 수요조사 결과 서브웨이 샌드위치, 수제햄버거, 닭강정이 간식으로 선정되었습니다. 수요조사에 대한 많은 관심 감사드립니다~!\n\n간식행사 신청 구글폼: https://forms.gle/xYWHZZVXsZHLTtRN6\n\n🎁참여 방식 : 사전 신청 기간에 구글폼 \"선착순 신청\" 후, 반실에서 \"대면 수령\"\n🎁사전 신청 시간 : 26. 10. 09. (금) 17시~ (선착순 26명 마감)\n*17시 이전에 구글폼 제출 시 무효 처리되니, 꼭 17시 이후에 제출하시기 바랍니다.\n🎁실제 수령 시간 : 26. 10. 14. (수) 18시 ~ 18시 30분\n🎁실제 수령 장소 : 구법학관 D반 반실\n🎁메뉴 : 서브웨이 스파이시 쉬림프 샌드위치 + 칠성사이다제로 [10개] // 한솥도시락 닭강정 + 치킨마요 + 펩시제로라임 [8개] // 퍽앤어니언 어니언치즈버거 세트 (코카콜라 오리지널) [8개]\n\n❗학생회비 납부자만 신청 가능합니다.\n❗대면으로 본인이 수령함이 원칙입니다.\n❗명단 확정자(사전 신청자 가운데 선착순 26명)에 한하여 나눔합니다.\n❗메뉴 선택은 행사 당일 선착순으로  진행합니다.\n\n문의: 복지국장 김동운\n제작: 홍보국원 김선희",
